package cn.minidayz.patcher;
import java.io.*;import java.util.*;import java.util.zip.*;import org.json.*;
public final class DeliveryCli {
 static void check(boolean b,String s)throws Exception{if(!b)throw new Exception("TEST: "+s);}
 static byte[] cert;static File root;static JSONArray results=new JSONArray();
 interface Attempt {void run()throws Exception;}
 static void fail(String name,Attempt a)throws Exception{boolean rejected=false;try{a.run();}catch(Exception expected){rejected=true;System.out.println(name+": "+expected.getMessage());}check(rejected,name);results.put(name);}
 public static void main(String[] args)throws Exception{root=new File(args[0]);root.mkdirs();File delivery=new File(args[1]),apk=new File(args[2]),key=new File(args[3]);cert=FilesEx.read(new FileInputStream(args[4]),16384);final File engine=new File(delivery,"引擎包_1.5.5.zip");FeaturePackages.importFile(new File(delivery,"插件总包_1.5.5.zip"),root,cert,FilesEx.QUIET);final File collection=new File(root,"module.zip");JSONObject m=FeaturePackages.read(collection,cert);check(m.getJSONArray("_features").length()==8,"feature count");check(m.getJSONArray("_rules").length()==3092,"rule count");final PatchEngine p=new PatchEngine(cert);final File source=apk;fail("missing engine rejected",new Attempt(){public void run()throws Exception{p.inspect(source,collection,FilesEx.QUIET);}});p.externalEngine=engine;ExternalEngine.verify(engine,cert);PatchEngine.Plan plan=p.inspect(apk,collection,FilesEx.QUIET);check(plan.profile!=null,"exact source matched");results.put("signed bundle imported and exact APK matched");
 final File bad=new File(root,"bad-engine.zip");ZipFile original=new ZipFile(engine);ZipOutputStream output=new ZipOutputStream(new FileOutputStream(bad));try{for(ZipEntry e:FilesEx.entries(original).values()){byte[] data=FilesEx.read(original.getInputStream(e),16777216);if(e.getName().equals("classes.dex"))data[100]^=1;output.putNextEntry(new ZipEntry(e.getName()));output.write(data);output.closeEntry();}}finally{output.close();original.close();}fail("corrupt engine code rejected",new Attempt(){public void run()throws Exception{ExternalEngine.verify(bad,cert);}});
 final File badSig=new File(root,"bad-feature.zip");File feature=new File(delivery,"功能分包/01_crafting-and-custom-items.zip");check(feature.isFile(),"feature filename");original=new ZipFile(feature);output=new ZipOutputStream(new FileOutputStream(badSig));try{for(ZipEntry e:FilesEx.entries(original).values()){byte[] data=FilesEx.read(original.getInputStream(e),16777216);if(e.getName().equals("feature.sig"))data[0]^=1;output.putNextEntry(new ZipEntry(e.getName()));output.write(data);output.closeEntry();}}finally{output.close();original.close();}final String prior=FilesEx.sha(collection,FilesEx.QUIET);fail("tampered feature rejected",new Attempt(){public void run()throws Exception{FeaturePackages.importFile(badSig,root,cert,FilesEx.QUIET);}});check(prior.equals(FilesEx.sha(collection,FilesEx.QUIET)),"failed import preserves selection");final File wrongBase=new File(root,"wrong.unity3d");FilesEx.write(wrongBase,new byte[]{1,2,3});fail("wrong game data rejected",new Attempt(){public void run()throws Exception{ExternalEngine.apply(engine,cert,"unityfs-json-155",wrongBase,new File(root,"wrong-output"),new File(root,"wrong-work"),new JSONArray(),FilesEx.QUIET);}});FeaturePackages.importFile(new File(delivery,"自定义总包验证.zip"),root,cert,FilesEx.QUIET);check(FeaturePackages.read(collection,cert).getJSONArray("_rules").length()==3092,"unsigned outer with signed children works");results.put("user-repacked outer bundle accepted after child signature checks");
 JSONArray inventory=FeaturePackages.inventory(root);ArrayList<String> ids=new ArrayList<String>();for(int i=0;i<inventory.length();i++)if(!inventory.getJSONObject(i).getString("id").equals("isolation-core"))ids.add(inventory.getJSONObject(i).getString("id"));boolean[] on=new boolean[ids.size()];FeaturePackages.select(root,ids,on,cert,FilesEx.QUIET);check(FeaturePackages.read(collection,cert).getJSONArray("_rules").length()==0,"disable features");FeaturePackages.importFile(feature,root,cert,FilesEx.QUIET);check(FeaturePackages.read(collection,cert).getJSONArray("_features").length()==1,"single feature import updates one feature");Arrays.fill(on,true);FeaturePackages.select(root,ids,on,cert,FilesEx.QUIET);results.put("feature selection and individual update verified");
 File game=new File(root,"generated.apk");game.delete();p.build(apk,collection,key,new File(root,"work"),game,new FilesEx.Watch(){public boolean cancelled(){return false;}public void progress(long d,long t){}public void stage(String s,String msg){System.out.println(s+": "+msg);}},null);Signing.verify(game,Signing.CERT_SHA,FilesEx.QUIET);results.put("full APK rebuild and signature verification passed");JSONObject report=new JSONObject().put("checks",results).put("game_sha256",FilesEx.sha(game,FilesEx.QUIET)).put("game_bytes",game.length()).put("android_device_test","NOT_RUN").put("external_engine_execution","same Java bytecode on JVM; test-only DexClassLoader bridge");FilesEx.write(new File(delivery,"完整流程验证.json"),report.toString(2).getBytes("UTF-8"));System.out.println(report.toString(2));}
}
